from pathlib import Path
import json,hashlib
p=Path(__file__).parent
c=json.loads((p/'input-contract.json').read_text(encoding='utf-8-sig'))
q=p/'lesson-03.md'; t=q.read_text(encoding='utf-8-sig').replace('\n+To scale','\nTo scale').replace('From depth 1 to 2, give subcell length/area/volume factors and verify total volume for the toy Group.','Derive the cell and distinct corner counts at depth 2 from cells per axis. Then from depth 1 to 2, give subcell length/area/volume factors and verify total volume for the toy Group.').replace('**Answer:** Factors are 1/2,1/4,1/8.','**Answer:** Depth 2 has 3×4=12 cells per axis, so 12^3=1728 cells and 13^3=2197 distinct corners. Factors are 1/2,1/4,1/8.')
q.write_text(t,encoding='utf-8')
for q in p.glob('lesson-*.md'): q.write_text(q.read_text(encoding='utf-8-sig'),encoding='utf-8')
source_records=[]
for s in c['sources']:
 actual=hashlib.sha256(Path(s['path']).read_bytes()).hexdigest()
 assert actual==s['sha256']
 source_records.append(dict(**s,actual_sha256=actual,hash_match=True,evidence_class='archival source; source-reported status distinct from fresh finite arithmetic'))
provenance=dict(sources=source_records,active_generation=c['source_routing']['snapshot_generation'],manifest_sha256=c['source_routing']['manifest_sha256'],retrieval='Krytronx capabilities and hybrid RAG search; rerank false. RAG returned integration links rather than full mathematical M03; authoritative local sources read in place.',direct_pointers=['S02#/backbone_sequence/1','S02#/backbone_sequence/2','S02#/supergroup_uniqueness','S03#/authority_contract','S03#/findings'],source_gaps=['Full corpus proof bodies and infinite inverse-limit theorem were not replayed; not needed for finite assessed operations.'],fresh_checks='Source file hashes and finite arithmetic only; no promotion of archival VERIFIED_FROZEN or compiler authority.')
(p/'source-provenance.json').write_text(json.dumps(provenance,indent=2),encoding='utf-8')
lines=['# Source notes','', 'Read-only files were hashed in place; no raw source snapshots were retained. Exact paths and full SHA-256 values follow. The mature S02 M03 definitions govern this finite course. S01 is historical/corrected provenance; S04 is an archival audit; S05 is background context. Hash verification does not promote any source-reported proof status.','']
for s in source_records: lines+=['## '+s['id'], '', '- Path: `'+s['path']+'`','- SHA-256: `'+s['sha256']+'`','- Match: true. Evidence class: archival source.','']
lines+=['## Claim routing and corrections','', '| Lesson content | Exact JSON pointer | Treatment |','|---|---|---|', '| Half-open ownership | S02 /backbone_sequence/1/definitions and /boundary_rule | Restated finite prerequisite |','| Window, Group, Supergroup and sampling counts | S02 /backbone_sequence/2/typed_finite_objects | Source definitions plus fresh finite counting |','| Dyadic and ternary rules | S02 /backbone_sequence/2/recursions | Kept as separate types and counters |','| Rung equation/domain | S02 /supergroup_uniqueness | Fresh finite proof over nonnegative integers |','| Source status discipline | S03 /authority_contract | Reported status stays source-reported |','| Historical spacing correction | S03 /findings/4 | No superseded numeric spacings used |','', 'M03 requires mathematical-backbone M02. This is unrelated to the integration compiler module also named M03. No integration authority is inferred from the shared label. S02 M02/M03 proof text contains origin-free dot-product lines; when referring to affine positions the correct form retains x−O_K or p−O_K. This course does not use those dot-product computations. It retains half-open region ownership separately from closed boundary sampling.','', 'The classroom volume basis has rows [[1,1,0],[0,2,0],[0,0,−3]], meaning edge columns a=(1,0,0), b=(1,2,0), c=(0,0,−3), arbitrary length units. It is not the locked Cell3 basis. Its negative determinant is intentional in the analogue; positive volume uses magnitude. No physical constant is substituted.','', 'Balanced ternary digit order and reconstruction conventions are explicitly taught finite representations of the source modular system. Rung odd/even arithmetic is not detector parity, carry parity, chirality or a projective sign. Detail coordinates are retained, including zero. No measured data or physical mechanism is introduced.','', 'Krytronx generation and manifest: `'+c['source_routing']['snapshot_generation']+'`. Capabilities were read and hybrid RAG searched with rerank=false. Integration search hits did not supply the full M03 mathematical text; the supplied local file was read directly and verified instead. Full infinite-history proof bodies were not replayed and are recognition-only here. There is no source gap in the finite core definitions or calculations.']
(p/'sources.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
# Concrete coverage rows follow actual authored explanation/practice IDs.
lines=['# Course map — Recursive K-Field Geometry and Address Histories','', 'Audience: high-school seniors with signed arithmetic, fractions, powers and coordinate reading. Six lessons occupy seven 55-minute core periods; the capstone takes two more. Course 05 capabilities are restated as operational bridges in lessons 01–03, so core tasks do not depend on an unavailable prior lesson file.','', 'Dependency chain: lesson-01 → lesson-02 → lesson-03 → lesson-04 → lesson-05 → lesson-06 → capstone. Unit A (01–03) develops geometry and typed counts. Unit B (04–06) develops modular words and lossless histories.','', '| Concept | Introduction/explanation | Worked | Answered practice | Diagnostic | Later use |','|---|---|---|---|---|---|']
for i,row in enumerate(c['coverage_matrix'],1):
 stem=f'C06.{i:02d}'; extra='; '+stem+'-E2 / W2 / P2 / D2' if i<=3 else ''
 lines.append(f"| {row['concept_id']} {row['concept']} | lesson-{i:02d}: {stem}-E1{extra} | {stem}-W1 | {stem}-P1 | {stem}-D1 | "+(f'lesson-{i+1:02d}' if i<6 else 'capstone')+' |')
lines+=['', 'Every E/W/P/D identifier is a literal heading or item in its lesson. E2 rows cover distinct typed objects, rung domain, and half-step sheets respectively. All P items have worked answers.','', '## Capstone backward map','', '| Step | Named input → required output | Earlier explanation | Worked example | Independently answered practice | Check |','|---|---|---|---|---|---|']
ops=['[0,1), n2≤3 → all intervals, indices and parents','moduli 1,3,9 → one-coordinate tree and 3D counts','outer3B,n2=0..2 → cells/corners and scale factors','integers5,8 → three signed digits and decodings','words5,8 → depth3,2,1 compatibility checks','indices/words → typed coarse-plus-detail recovery records','window/Group/Supergroup → object-specific counts','equation and integer domain → unique rung pair and bounds','centered9B/3B → half-step counts and all reachable lambda sheets']
for j,b in enumerate(c['capstone_specification']['backward_map']):
 stem=b['worked_example_id'].rsplit('-W',1)[0]; num=b['worked_example_id'][-1]
 lines.append(f"| {b['step_id']} | {ops[j]} | {b['introduction']}: {stem}-E{num} | {b['worked_example_id']} | {b['prior_practice_id']} | {b['diagnostic_id']} |")
lines+=['', '## Pacing and scope decisions','', 'Lesson03 retains its stable checkpoint but spans two periods (110 minutes), as approved. All other lessons use 55 minutes: 20 explanation/worked examples,15 practice,15 diagnostics/feedback,5 transition. Lesson03 uses that breakdown twice. Capstone periods divide steps01–04 and05–09 with review time. Infinite inverse limits and abstract quotient proofs are recognition-only; no calculus, general matrix inversion or physical modeling is assessed.','', 'Assumptions: a topical short course; exact integer and fraction computations; Markdown delivery; no new source measurements. Source evidence and arithmetic derivations remain separate. All removed address detail remains in reversible records.']
(p/'course-map.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
# Persist drafted statuses with hashes; do not claim audit completion.
m=json.loads((p/'manifest.json').read_text())
for cp in m['checkpoints']:
 cp['status']='drafted'; cp['sha256']=hashlib.sha256((p/cp['path']).read_bytes()).hexdigest(); cp['summary']='Complete lesson authored; final independent audit pending'
m['next_action']='Complete supporting materials and independent checks'
(p/'manifest.json').write_text(json.dumps(m,indent=2),encoding='utf-8')
